-- r483 local harness seed: the 10 workshop stations and 47 bays as configured on staging (22 Oct 2026; technician ids replaced
-- by a placeholder) and synthetic bookings only (no vehicles, customers, stock numbers or real booking rows).
-- Synthetic bookings: 3 per active non-sublet bay outside Fab 03-13, plus 2 deleted ones; none on the Fab bays r483 hides.
SELECT gen_random_uuid(), b.stage_id, b.id, (ARRAY['planned','queued','started'])[g], timestamptz '2026-10-26 08:00+08' + (g||' days')::interval,
       timestamptz '2026-10-26 10:00+08' + (g||' days')::interval, NULL, 1
  FROM public.workshop_bays b, generate_series(1,3) g WHERE b.is_active AND NOT b.is_sublet_row AND b.code NOT IN (SELECT 'FABRICATION-BAY-'||lpad(n::text,2,'0') FROM generate_series(3,13) n);
SELECT gen_random_uuid(), b.stage_id, b.id, 'planned', timestamptz '2026-10-20 08:00+08', timestamptz '2026-10-20 09:00+08', timestamptz '2026-10-20 07:00+08', 2
  FROM public.workshop_bays b WHERE b.code IN ('FITTING-BAY-01','HOIST-BAY-01');
